// Adapta dados do SELECT pra ficar compatível com nós copiados do principal
// (que referenciam $('3. Prepare Metadata').first().json.*).
const meeting = $input.first().json;
if (!meeting || !meeting.id) {
  throw new Error('meeting não encontrada: ' + JSON.stringify(meeting).slice(0, 200));
}
return [{
  json: {
    meeting_id: meeting.id,
    user_id: meeting.user_id,
    transcription: meeting.transcription || '',
    duration_seconds_local: meeting.duration_seconds || 0,
    recorded_at: meeting.recorded_at,
    source: meeting.source || 'segmented',
    meeting_type: meeting.meeting_type || 'desconhecido',
    segments_local: meeting.segments || []
  }
}];

// Usa transcrição + segments já prontos do Mac.
// Formato compatível: { text, duration, language, segments }.
const meta = $('3. Prepare Metadata').first().json;
return [{
  json: {
    text: meta.transcription || '',
    duration: meta.duration_seconds_local || 0,
    language: 'pt',
    segments: meta.segments_local || [],
  }
}];

// Parseia o JSON retornado pelo GPT e prepara items para INSERT em tarefas.
const meetingId = $('3. Prepare Metadata').first().json.meeting_id;
const raw = $input.first().json;

// O nó openAi v1.7 retorna o JSON em diferentes shapes — normaliza.
let parsed;
if (raw.message && raw.message.content) {
  parsed = typeof raw.message.content === 'string' ? JSON.parse(raw.message.content) : raw.message.content;
} else if (raw.content) {
  parsed = typeof raw.content === 'string' ? JSON.parse(raw.content) : raw.content;
} else if (raw.text) {
  parsed = typeof raw.text === 'string' ? JSON.parse(raw.text) : raw.text;
} else if (raw.summary && Array.isArray(raw.actions)) {
  parsed = raw;
} else {
  throw new Error('Não foi possível parsear resposta do GPT: ' + JSON.stringify(raw).slice(0, 500));
}

const { summary = '', actions = [] } = parsed;
const rawJson = JSON.stringify(parsed);

if (!actions.length) {
  return [{
    json: {
      meeting_id: meetingId,
      summary,
      raw_ai_response: rawJson,
      no_actions: true
    }
  }];
}

// ── REGRAS NOVAS: coerência determinística owner↔acao, owner∈pessoas, prazo temporal ──
function __normOwner(o){ const s=(o==null?'':String(o)).trim(); if(!s) return 'vitor'; if(/^vitor$/i.test(s)) return 'vitor'; if(/^speaker\b/i.test(s)) return '?'; return s; }
function __coerceAcao(owner, acao){ const o=__normOwner(owner); if(o==='vitor') return 'executar'; return ['cobrar','aguardar'].includes(acao)?acao:'cobrar'; }
function __cleanPrazo(t){ if(t==null) return null; const s=String(t).trim(); if(!s) return null; const re=/(hoje|amanh[\u00e3a]|ontem|segunda|ter[\u00e7c]a|quarta|quinta|sexta|s[\u00e1a]bado|domingo|semana|m\u00eas|meses|que vem|daqui a|fim de semana|feriado|manh[\u00e3a]|tarde|noite|madrugada|daily|janeiro|fevereiro|mar[\u00e7c]o|abril|maio|junho|julho|agosto|setembro|outubro|novembro|dezembro|\d{1,2}\s*\/\s*\d{1,2}|dia\s+\d{1,2}|\d{1,2}\s*h\b|\d{1,2}:\d{2})/i; return re.test(s) ? s : null; }
function __ensurePessoas(owner, pessoas){ let arr=(Array.isArray(pessoas)?pessoas:[]).filter(p=>!/^speaker\b/i.test(String(p==null?'':p).trim())); const o=__normOwner(owner); if(o!=='vitor' && o!=='?' && !arr.some(p=>String(p==null?'':p).trim().toLowerCase()===o.toLowerCase())) arr.unshift(o); return arr; }

return actions.map((a, i) => ({
  json: {
    meeting_id: meetingId,
    summary,
    raw_ai_response: rawJson,
    titulo: a.titulo || '(sem título)',
    descricao: a.descricao || '',
    owner: __normOwner(a.owner),
    prazo: a.prazo_iso || null,
    prazo_text: __cleanPrazo(a.prazo_text),
    prioridade: ['baixa','media','alta','urgente'].includes(a.prioridade) ? a.prioridade : 'media',
    evidencia: a.evidencia || '',
    pessoas_raw: JSON.stringify(__ensurePessoas(a.owner, a.pessoas_envolvidas)),
    area_raw: a.area || null,
    acao: __coerceAcao(a.owner, a.acao),
    idx: i,
    total: actions.length
  }
}));
